export function getProStrings(lang = 'en') {
  const norm = String(lang || 'en').toLowerCase().replace('_', '-');
  if (PRO_I18N[norm]) return PRO_I18N[norm];
  const base = norm.split('-')[0];
  return PRO_I18N[base] || PRO_I18N.en;
}
